//! 🧪️ Original export work exposes bounded source demand and never creates the outer owner's publications.
use super::*;
fn operation()->Operation{Operation::new(semio_framework_job::OperationId(97),semio_framework_job::RevisionId(1),semio_framework_job::Generation(2),17)}
fn fixture()->(LayoutExportJob,Arc<LayoutSnapshot>){let snapshot=Arc::new(semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document());let operation=operation();let request=LayoutExportRequest{kind:LayoutExportKind::Svg,page_id:None,snapshot:Arc::clone(&snapshot),preflight_json:None,parent_document_id:"actual-layout".into(),canonical_base_revision_hex:"1".repeat(64)};(LayoutExportJob::from_admitted(operation,(operation.operation,operation.generation),request,ArtifactOutputChunks::new(MAX_LAYOUT_EXPORT_OUTPUT_BYTES)),snapshot)}
fn close(job:&mut LayoutExportJob){InteractiveJob::begin_close(job);let operation=operation();let mut caller=layout_export_fixture_caller(operation,operation.generation);for _ in 0..100000{if InteractiveJob::terminal_is_empty(job){break}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|Ok(InteractiveJob::close_step(job,cx))).unwrap().unwrap();}assert!(InteractiveJob::terminal_is_empty(job));assert!(job.drawing_consumers_terminal_is_empty());caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK)}
#[test]fn neutral_read_gate_requires_a_real_loan_only_for_active_drawing(){let laws:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let original=String::from("actual borrowed original");for row in laws["cases"].as_array().unwrap(){let source=match row["source"]["kind"].as_str(){Some("document")=>Some(DrawingSourceAddress::Document),Some("page")=>Some(DrawingSourceAddress::Page(row["source"]["page"].as_u64().unwrap()as usize)),_=>None};let read=row["read"].as_bool().unwrap().then_some(&original);assert_eq!(require_original_drawing_read(source,read).is_ok(),row["accept"].as_bool().unwrap());if let Some(value)=require_original_drawing_read(source,read).ok().flatten(){assert!(std::ptr::eq(value,&original))}}}
#[test]fn publication_free_work_preserves_the_original_slot_and_each_cancellation_cut(){for cut in[0,1,2,3,8,16,32]{let(mut job,_snapshot)=fixture();let operation=operation();let mut caller=layout_export_fixture_caller(operation,operation.generation);for _ in 0..cut{let step=caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|Ok(job.advance_original_work(cx,None))).unwrap().unwrap();assert_ne!(step,LayoutExportWorkTurn::Pending);assert!(job.slot.publication.is_none());assert!(!job.slot.delivered);}assert_eq!(job.work_units,cut);assert_eq!(job.required_drawing_source(),None);close(&mut job);caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK)}}
#[test]fn active_consumer_reports_its_exact_numeric_source_and_refuses_a_missing_original(){for source in[DrawingSourceAddress::Document,DrawingSourceAddress::Page(0)]{let(mut job,_snapshot)=fixture();job.stage=ExportStage::Plan;job.target_page=Some(0);job.drawing=Some(DrawingCompositionState::new());job.drawing.as_mut().unwrap().begin(source,DrawingPlacement::Canvas,LayoutBounds{x:0.0,y:0.0,width:200.0,height:100.0,rotation:0.0}).unwrap();job.drawing_source=Some(source);assert_eq!(job.required_drawing_source(),Some(source));assert!(!job.drawing_consumers_terminal_is_empty());let operation=operation();let mut caller=layout_export_fixture_caller(operation,operation.generation);for grant in[semio_framework_value::RetainedCloneGrant{maximum_items:1,..LAYOUT_EXPORT_FIXTURE_TURN},semio_framework_value::RetainedCloneGrant{maximum_copy_bytes:15,..LAYOUT_EXPORT_FIXTURE_TURN},semio_framework_value::RetainedCloneGrant{maximum_depth:0,..LAYOUT_EXPORT_FIXTURE_TURN}]{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|Ok(job.advance_original_work(cx,None))).unwrap().unwrap());assert_eq!(step,LayoutExportWorkTurn::Pending);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let error=caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|Ok(job.advance_original_work(cx,None))).unwrap().unwrap_err();assert!(error.primary.message().contains("original qualified Drawing"));assert!(job.slot.publication.is_none());assert_eq!(job.work_units,0);close(&mut job);caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK)}}
